/*SELECT FROM [dbo].[OINM] T1 INNER JOIN OWHS T2 ON T2.WhsCode=T1.Warehouse*/DECLARE @StartDate NVARCHAR(20);DECLARE @EndDate NVARCHAR(20);DECLARE @Whscode NVARCHAR(50);DECLARE @StartItemCode NVARCHAR(50);DECLARE @EndItemCode NVARCHAR(50);/* WHERE */SET @StartDate =/* T1.DocDate */ N'[%0]';SET @EndDate =/* T1.DocDate */ N'[%1]';SET @Whscode =/* t1.Warehouse*/N'[%2]';SET @StartItemCode =/* t1.ItemCode*/N'[%3]';SET @EndItemCode =/* t1.ItemCode*/N'[%4]';IF LEN(@Whscode)=0 SET @Whscode=NULL;IF LEN(@StartItemCode)=0 SET @StartItemCode=NULL;IF LEN(@EndItemCode)=0 SET @EndItemCode=NULL;-- T_Result: Block ngoài cùng để áp dụng điều kiệnSELECT     T_Result.[Tên_Chi_Nhánh],    T_Result.[Warehouse],    T_Result.[WH-name],        -- [CỘT MỚI]: Lấy Mã và Tên Tài khoản Kho từ Nhóm mặt hàng    T_Result.[Invntry_Account] AS [Mã_Tài_Khoản],    T_Result.[Account_Name] AS [Tên_Tài_Khoản],        T_Result.[ItemCode],    T_Result.[ItemName],    T_Result.[ItemGroupCode],    T_Result.[ItemGroupName],    T_Result.[InvntryUom],    T_Result.[Opening Qty],    T_Result.[Opening Value],    T_Result.[Input Qty],    T_Result.[Input Value],    T_Result.[Output Qty],    T_Result.[Output Value],    T_Result.[Ending Qty],        -- LOGIC XỬ LÝ GIÁ TRỊ:     -- Nếu Tồn kho = 0 -> Ép Giá trị = 0    -- Nếu Tồn kho > 0 -> Lấy Tồn kho * Giá vốn bình quân    CASE         WHEN ROUND(T_Result.[Ending Qty], 4) = 0 THEN 0        ELSE ROUND(T_Result.[Ending Qty] * ISNULL(T_Result.[Calculated_Unit_Cost], 0), 2)    END AS [Ending Value],    -- [CẬP NHẬT]: Hiện thị Giá vốn bình quân đã tính toán ở cuối cùng    ROUND(ISNULL(T_Result.[Calculated_Unit_Cost], 0), 4) AS [Giá_Vốn_BQ_Cuối_Kỳ],        -- [CẬP NHẬT]: Thêm cột ghi rõ thời điểm chốt giá vốn (Lấy theo thông số Date To)    ISNULL(@EndDate, N'Kỳ hiện tại') AS [Thời_Điểm_Tính_Giá_Vốn]FROM (    -- Block trung gian: Tính toán Giá vốn bình quân cho từng mã hàng    SELECT         T_Main.*,                -- Dùng Window Function để tính Unit Cost = (Tổng Giá trị toàn công ty) / (Tổng Số lượng toàn công ty)        SUM(T_Main.[Raw Ending Value]) OVER (PARTITION BY T_Main.ItemCode) /         NULLIF(SUM(T_Main.[Ending Qty]) OVER (PARTITION BY T_Main.ItemCode), 0) AS [Calculated_Unit_Cost]            FROM (        -- T_Main: Block tính toán dữ liệu thô gốc        SELECT                 ISNULL((                   SELECT TOP 1 T_BPL.BPLName                    FROM OWHS T_WHS                    INNER JOIN OBPL T_BPL ON T_WHS.BPLid = T_BPL.BPLId                    WHERE T_WHS.WhsCode = tmp.Warehouse               ), N'Trụ sở chính') AS [Tên_Chi_Nhánh],                tmp.Warehouse,               (SELECT Whsname FROM owhs WHERE whscode = tmp.Warehouse) AS [WH-name],                              -- [LẤY TÀI KHOẢN TỪ BẢNG NHÓM MẶT HÀNG OITB]               T10.BalInvntAc AS [Invntry_Account],               (SELECT AcctName FROM OACT WHERE AcctCode = T10.BalInvntAc) AS [Account_Name],               tmp.ItemCode,               tmp.ItemName,               T9.ItmsGrpCod AS [ItemGroupCode],               T10.ItmsGrpNam AS [ItemGroupName],               T9.InvntryUom,               SUM(tmp.BeginQty) AS [Opening Qty],               SUM(tmp.BeginBalance) AS [Opening Value],               SUM(tmp.InQty) AS [Input Qty],               SUM(tmp.InBalance) AS [Input Value],               SUM(tmp.OutQty) AS [Output Qty],               SUM(tmp.OutBalance) AS [Output Value],               ROUND((SUM(tmp.BeginQty) + SUM(tmp.InQty) - SUM(tmp.OutQty)), 4) AS [Ending Qty],               (SUM(tmp.BeginBalance) + SUM(tmp.InBalance) - SUM(tmp.OutBalance)) AS [Raw Ending Value]        FROM (                 SELECT T0.ItemCode, T1.ItemName, T0.Warehouse, 0 BeginQty, 0 BeginBalance, 0 InQty, SUM(T0.TransValue) InBalance, 0 OutQty, 0 OutBalance                 FROM OINM T0 INNER JOIN OITM T1 ON T0.ItemCode=T1.ItemCode                 WHERE (T0.[DocDate]>=@StartDate OR @StartDate IS NULL OR @StartDate=N'') AND (T0.[DocDate]<=@EndDate OR @EndDate IS NULL OR @EndDate=N'') AND T0.TransValue>0                 GROUP BY T0.ItemCode, T1.ItemName, T0.Warehouse                 UNION ALL                 SELECT T0.ItemCode, T1.ItemName, T0.Warehouse, 0, 0, 0, 0, 0, -SUM(T0.TransValue)                 FROM OINM T0 INNER JOIN OITM T1 ON T0.ItemCode=T1.ItemCode                 WHERE (T0.[DocDate]>=@StartDate OR @StartDate IS NULL OR @StartDate=N'') AND (T0.[DocDate]<=@EndDate OR @EndDate IS NULL OR @EndDate=N'') AND T0.TransValue<0                 GROUP BY T0.ItemCode, T1.ItemName, T0.Warehouse                 UNION ALL                 SELECT T0.ItemCode, T1.ItemName, T0.Warehouse, 0, 0, SUM(T0.InQty), 0, SUM(T0.OutQty), 0                 FROM OINM T0 INNER JOIN OITM T1 ON T0.ItemCode=T1.ItemCode                 WHERE (T0.[DocDate]>=@StartDate OR @StartDate IS NULL OR @StartDate=N'') AND (T0.[DocDate]<=@EndDate OR @EndDate IS NULL OR @EndDate=N'')                 GROUP BY T0.ItemCode, T1.ItemName, T0.Warehouse                 UNION ALL                 SELECT T0.ItemCode, T1.ItemName, T0.Warehouse, (SUM(T0.InQty) - SUM(T0.OutQty)), SUM(T0.TransValue), 0, 0, 0, 0                 FROM OINM T0 INNER JOIN OITM T1 ON T0.ItemCode=T1.ItemCode                 WHERE T0.[DocDate]<@StartDate                 GROUP BY T0.ItemCode, T1.ItemName, T0.Warehouse        ) tmp        INNER JOIN OITM T9 ON tmp.ItemCode = T9.ItemCode        INNER JOIN OITB T10 ON T9.ItmsGrpCod = T10.ItmsGrpCod        WHERE (tmp.Warehouse = @Whscode OR @Whscode IS NULL)           AND (tmp.ItemCode >= @startItemcode OR @startItemcode IS NULL)             AND (tmp.ItemCode <= @enditemcode OR @enditemcode IS NULL)                -- Nhớ GROUP BY thêm cột T10.BalInvntAc để hệ thống không báo lỗi        GROUP BY tmp.ItemCode, tmp.ItemName, T9.Spec, T9.InvntryUom, tmp.Warehouse, T9.ItmsGrpCod, T10.ItmsGrpNam, T10.BalInvntAc    ) T_Main) T_ResultORDER BY T_Result.ItemCode, T_Result.Warehouse